// front/components/SongCard.tsx
import { useState, useEffect } from "react";
import { Song } from "@/types/song";
import { updateSong } from "@/lib/api";

export default function SongCard({
  song,
  onListened,
}: {
  song: Song;
  onListened: (message: string) => void;
}) {
  const friendTags =
    typeof song.friends_recommended === "string"
      ? Array.from(
          new Set(
            song.friends_recommended
              .split(",")
              .map((t: string) => t.trim())
              .filter((t: string) => t.length > 0),
          ),
        )
      : [];
  const myTags = song.my_tags
    ? Array.from(
        new Set(
          song.my_tags
            .split(",")
            .map((t: string) => t.trim())
            .filter((t: string) => t.length > 0),
        ),
      )
    : [];
  const [tagInput, setTagInput] = useState("");
  const [saving, setSaving] = useState(false);
  const [rating, setRating] = useState<number>(song.rating ?? 0);

  useEffect(() => {
    setRating(song.rating ?? 0);
  }, [song.rating]);

  useEffect(() => {
    if (song.listened) {
      setTagInput("");
    }
  }, [song.listened]);

  return (
    <div
      style={{
        display: "flex",
        gap: 16,
        alignItems: "flex-start",
        padding: 16,
        marginBottom: 20, // 🔥 spacing between movies
        borderRadius: 14,
        background: "#0b0b0b",
        border: "1px solid #222",
      }}
    >
      {song.image_url && (
        <img
          src={song.image_url}
          alt={song.title}
          width={90}
          style={{
            borderRadius: 8,
            flexShrink: 0, // 🔥 prevents resizing
            alignSelf: "flex-start",
          }}
        />
      )}

      <div style={{ flex: 1 }}>
        {/* Title + year + listened */}
        <h3 style={{ margin: 0 }}>{song.title ?? song.song_id}</h3>

        {song.year && (
          <div style={{ fontSize: 13, opacity: 0.7 }}>{song.year}</div>
        )}

        <div
          style={{
            marginTop: 6,
            fontSize: 12,
            fontWeight: 600,
            color: song.listened ? "#4caf50" : "#ff9800",
          }}
        >
          {song.listened ? "● Listened" : "● Not listened"}
        </div>
        <div
          style={{
            marginTop: 12,
            padding: 12,
            borderRadius: 10,
            background: "#121212",
          }}
        >
          {song.listened && (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr 1fr",
                gap: 16,
                marginTop: 12,
              }}
            >
              {/* Recommended by */}
              <div>
                <div style={{ fontSize: 12, opacity: 0.7 }}>Recommended by</div>
                <div
                  style={{
                    display: "flex",
                    gap: 6,
                    flexWrap: "wrap",
                    marginTop: 4,
                  }}
                >
                  {friendTags.map((friend, index) => (
                    <span
                      key={`${friend}-${index}`}
                      style={{
                        fontSize: 12,
                        padding: "2px 8px",
                        borderRadius: 12,
                        background: "#222",
                        border: "1px solid #444",
                      }}
                    >
                      {friend}
                    </span>
                  ))}
                </div>
              </div>

              {/* My tags */}
              <div>
                <div style={{ fontSize: 12, opacity: 0.7 }}>My tags</div>
                <div
                  style={{
                    display: "flex",
                    gap: 6,
                    flexWrap: "wrap",
                    marginTop: 4,
                  }}
                >
                  {myTags.map((tag, index) => (
                    <span
                      key={`${tag}-${index}`}
                      style={{
                        fontSize: 12,
                        padding: "2px 8px",
                        borderRadius: 12,
                        background: "#1a237e",
                        border: "1px solid #3949ab",
                      }}
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </div>

              {/* Rating */}
              <div style={{ marginTop: 10 }}>
                <div style={{ fontSize: 12, opacity: 0.7 }}>Rating:</div>
                <div
                  style={{
                    display: "flex",
                    gap: 4,
                    marginTop: 4,
                  }}
                >
                  {[1, 2, 3, 4, 5].map((star) => (
                    <button
                      key={star}
                      onClick={async () => {
                        setRating(star);
                        const res = await updateSong(song.song_id, {
                          rating: star,
                        });
                        const data = await res.json();
                        onListened(data.message);
                      }}
                      style={{
                        background: "none",
                        border: "none",
                        cursor: "pointer",
                        fontSize: 20,
                        color: star <= rating ? "#FFD700" : "#555",
                      }}
                    >
                      ★
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {!song.listened && (
            <div>
              <div style={{ fontSize: 12, opacity: 0.7, marginBottom: 6 }}>
                My tags (comma-separated)
              </div>

              <input
                placeholder="e.g. moody,rainy-night"
                value={tagInput}
                onChange={(e) => setTagInput(e.target.value)}
                style={{
                  width: "100%",
                  padding: 8,
                  borderRadius: 6,
                  border: "1px solid #444",
                  background: "#0f0f0f",
                  color: "white",
                }}
              />

              <button
                disabled={saving}
                style={{
                  marginTop: 10,
                  padding: "8px 14px",
                  borderRadius: 8,
                  background: saving ? "#555" : "#1976d2",
                  color: "white",
                  border: "none",
                  cursor: saving ? "not-allowed" : "pointer",
                  fontWeight: 600,
                }}
                onClick={async () => {
                  setSaving(true);

                  const uniqueMyTags = Array.from(
                    new Set(
                      tagInput
                        .split(",")
                        .map((t) => t.trim())
                        .filter(Boolean),
                    ),
                  );

                  const res = await updateSong(song.song_id, {
                    listened: true,
                    my_tags: uniqueMyTags,
                  });

                  const data = await res.json();
                  onListened(data.message);
                  setSaving(false);
                }}
              >
                {saving ? "Saving..." : "Mark as Listened"}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
